"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[80125],{80125:function(e){e.exports=JSON.parse('{"content":"\\n## How to take a screen capture in AOSP\\nScreen capture is possible using the ```screencap``` tool in the AOSP environment.\\n```sh\\n{\\n    \\"title\\": \\"Use screencap\\"\\n}\\n---\\n$ adb exec-out screencap -p > capture.png\\n```\\nIt supports png, jpeg, and jpg formats, and distinguishes them by the filename\'s extension.\\n```c\\n{\\n    \\"title\\": \\"frameworks/base/cmds/screencap/screencap.cpp\\"\\n}\\n---\\n...\\n    if (argc == 1) {\\n        std::string_view filename = {argv[0]};\\n        if (filename.ends_with(\\".png\\")) {\\n            baseName = filename.substr(0, filename.size() - 4);\\n            suffix = \\".png\\";\\n            png = true;\\n        } else if (filename.ends_with(\\".jpeg\\")) {\\n            baseName = filename.substr(0, filename.size() - 5);\\n            suffix = \\".jpeg\\";\\n            jpeg = true;\\n        } else if (filename.ends_with(\\".jpg\\")) {\\n            baseName = filename.substr(0, filename.size() - 4);\\n            suffix = \\".jpg\\";\\n            jpeg = true;\\n        } else {\\n            baseName = filename;\\n        }\\n    }\\n...\\n```\\nUsing the display ID, you can also capture other display screens.\\nConnected display IDs can be checked with <mark>dumpsys</mark>.\\n```sh\\n{\\n    \\"title\\": \\"Use screencap in other display\\"\\n}\\n---\\n$ adb shell dumpsys SurfaceFlinger --display-id\\nDisplay 0 (HWC display 1): no identification data\\n  \\n$ adb exec-out screencap -d 0 -p > capture.png\\n```"}')}}]);